// Render an applies_when tree as short human-readable clauses, e.g.
// "doc_origin is DE" or "article_number is not empty".
//
// Used by the rule sentence in both the list and the builder banner. The tree
// shape is the shared one from the custom-validation rules; this module only
// turns it into words (no editing), so it stays independent of the builder.

import type {
  TransformationRuleAppliesWhen,
  TransformationRuleCondition,
} from 'src/services/settings/TransformationRulesApiService';
import { shortFieldName } from './transformation-rule-model';

/** Operators that assert on presence alone — they render without a value. */
const NO_VALUE_OPS = ['empty', 'not_empty'];

/** i18n key for each operator's short phrase. Mirrors OP_OPTIONS in the shared
 *  validation model, but translated (the list is user-facing prose here). */
const OP_PHRASE_KEYS: Record<string, string> = {
  eq: 'op_is',
  neq: 'op_is_not',
  in: 'op_is_one_of',
  not_in: 'op_is_not_one_of',
  contains: 'op_contains',
  starts_with: 'op_starts_with',
  ends_with: 'op_ends_with',
  empty: 'op_is_empty',
  not_empty: 'op_is_not_empty',
  gt: 'op_greater_than',
  lt: 'op_less_than',
  gte: 'op_at_least',
  lte: 'op_at_most',
  matches: 'op_matches',
};

type Translate = (key: string, params?: Record<string, unknown>) => string;

/** One leaf condition as a clause. A `not`-wrapped node is unwrapped and
 *  prefixed, matching how the builder round-trips negation. */
function leafPhrase(node: TransformationRuleCondition, t: Translate): string {
  let inner = node;
  let negated = false;
  if (node && typeof node === 'object' && 'not' in node && node.not) {
    inner = node.not as TransformationRuleCondition;
    negated = true;
  }
  const op = String(inner.op || 'eq');
  const field = shortFieldName(String(inner.field || '')) || t('phrase_a_field');
  const opWord = t(OP_PHRASE_KEYS[op] || op);

  let value = '';
  if (!NO_VALUE_OPS.includes(op)) {
    const raw = inner.value;
    if (Array.isArray(raw)) value = raw.join(', ');
    else if (raw !== undefined && raw !== null) value = String(raw);
  }

  const clause = value ? `${field} ${opWord} ${value}` : `${field} ${opWord}`;
  return negated ? `${t('phrase_not')} ${clause}` : clause;
}

/** Flatten one level of an applies_when tree into clause strings. A nested
 *  sub-group is rendered inline and parenthesised so the sentence still reads
 *  correctly without reproducing the whole tree structure. */
export function conditionPhrases(
  appliesWhen: TransformationRuleAppliesWhen | null,
  join: 'all' | 'any',
  t: Translate,
): string[] {
  if (!appliesWhen) {
    return [];
  }
  const list = (appliesWhen[join] as TransformationRuleCondition[]) || [];
  if (!Array.isArray(list)) {
    return [];
  }
  return list.map((raw) => {
    const asGroup = raw as TransformationRuleAppliesWhen;
    if (asGroup && typeof asGroup === 'object' && Array.isArray(asGroup.all)) {
      const inner = conditionPhrases(asGroup, 'all', t);
      return `(${inner.join(` ${t('join_and')} `)})`;
    }
    if (asGroup && typeof asGroup === 'object' && Array.isArray(asGroup.any)) {
      const inner = conditionPhrases(asGroup, 'any', t);
      return `(${inner.join(` ${t('join_or')} `)})`;
    }
    return leafPhrase(raw, t);
  });
}
