// ---- Row values (add_row) ------------------------------------------------

/** One column assignment on a row being added. `from` selects whether `value`
 *  is a literal or a namespaced field reference resolved on the document. */
export interface RowValue {
  col: string;
  from: 'static' | 'field';
  value: string;
}

export function newRowValue(col = ''): RowValue {
  return { col, from: 'static', value: '' };
}

/** The column assignments of an `add_row` step, normalised.
 *
 *  Two encodings arrive here. The API distinguishes a field reference from a
 *  literal by WHICH KEY IS PRESENT — `{col, source}` vs `{col, value}` — while
 *  the editor carries an explicit `from` discriminator, because a radio toggle
 *  needs somewhere to store "field, but nothing picked yet". `source` wins when
 *  present, so this reads a raw payload and an editor value alike.
 *
 *  Params are stored loosely (the backend takes a free-form object), so a
 *  payload written by another client still yields usable rows rather than
 *  throwing. */
export function rowValues(action: TransformationAction): RowValue[] {
  const raw = (action.params || {}).values;
  if (!Array.isArray(raw)) return [];
  return raw.map((v) => {
    const item = (v || {}) as Record<string, unknown>;
    const col = item.col == null ? '' : String(item.col);
    if (item.source !== undefined) {
      return { col, from: 'field', value: item.source == null ? '' : String(item.source) };
    }
    return {
      col,
      from: item.from === 'field' ? 'field' : 'static',
      value: item.value == null ? '' : String(item.value),
    };
  });
}

